private static void createGraph() {
    boolean[] states = {true, false};
    for (boolean wolf : states) {
        for (boolean sheep : states) {
            for (boolean vegetable : states) {
                for (boolean farmer : states) {
                    if (!isValid(wolf, sheep, vegetable, farmer)) {
                        continue;
                    }
                    Node node = new Node(wolf, sheep, vegetable, farmer);
                    node.setIndex(nodes.size());
                    nodes.add(node);
                }
            }
        }
    }
    edges = new int[nodes.size()][nodes.size()];
    for (int i = 0; i < nodes.size(); i++) {
        for (int j = 0; j < nodes.size(); j++) {
            edges[i][j] = canConnect(nodes.get(i), nodes.get(j)) ? 1 : 0;
        }
    }
    visit = new boolean[nodes.size()];
}

private static void searchWay() {
    int start = 0;
    int last = 0;
    for (int i = 0; i < nodes.size(); i++) {
        Node node = nodes.get(i);
        if (!node.getFarmer() && !node.getSheep() && !node.getVegetable() && !node.getWolf()) {
            start = i;
        }
        if (node.getFarmer() && node.getSheep() && node.getVegetable() && node.getWolf()) {
            last = i;
        }
    }
    DFS(nodes.get(start), nodes.get(last));
}

private static void DFS(Node startNode, Node lastNode) {
    stack.push(startNode);
    visit[startNode.index] = true;
    while (!stack.isEmpty()) {
        int index = stack.getTop().getIndex();
        if (index == lastNode.index) {
            results.add(stack.getList());
            stack.pop();
            visit[lastNode.index] = false;
            break;
        }
        while (startNode.flag < nodes.size()) {
            if (edges[index][startNode.flag] == 1 && !visit[startNode.flag]) {
                DFS(nodes.get(startNode.flag), lastNode);
            }
            startNode.flag++;
        }
        if (startNode.flag == nodes.size()) {
            stack.pop();
            startNode.flag = 0;
            visit[startNode.index] = false;
            break;
        }
    }
}

private static void showResult() {
    for (int i = 0; i < results.size(); i++) {
        System.out.println("第" + (i + 1) + "种答案");
        ArrayList<Node> result = results.get(i);
        for (int j = 0; j < result.size() - 1; j++) {
            Node now = result.get(j);
            Node next = result.get(j + 1);
            StringBuilder sb = new StringBuilder("农夫");
            if (now.getSheep() != next.getSheep()) {
                sb.append("带着羊");
            } else if (now.getWolf() != next.getWolf()) {
                sb.append("带着狼");
            } else if (now.getVegetable() != next.getVegetable()) {
                sb.append("带着菜");
            } else {
                sb.append("什么都不带");
            }
            if (next.getFarmer()) {
                sb.append("过到对岸。");
            } else {
                sb.append("回到原岸。");
            }
            System.out.println(sb.toString());
        }
        System.out.println();
    }
}

private static boolean isValid(boolean wolf, boolean sheep, boolean vegetable, boolean farmer) {
    return farmer == sheep || (wolf != sheep && sheep != vegetable);
}

private static boolean canConnect(Node i, Node j) {
    int count = 0;
    if (i.getWolf() != j.getWolf()) {
        count++;
    }
    if (i.getSheep() != j.getSheep()) {
        count++;
    }
    if (i.getVegetable() != j.getVegetable()) {
        count++;
    }
    return i.getFarmer() != j.getFarmer() && count <= 1;
}
